let activePHP=0,filesystemMutations=0,lastFilesystemScan=0,filesystemRevision=0,filesystemScan;
async function refreshFilesystem(){
if(!storage.enabled||filesystemMutations)return;
if(!filesystemScan&&Date.now()-lastFilesystemScan>=2000){
const revision=filesystemRevision;
filesystemScan=(async()=>{try{
const nodes=await scanStorage({root:explorerRoot,metadataDir:dir,db});
// A user action wins over an older scan snapshot. Retry on the next poll.
if(nodes&&revision===filesystemRevision&&!filesystemMutations){db.nodes=nodes;await save(false);}
}catch(error){console.error('Dateiabgleich:',error.message);}finally{lastFilesystemScan=Date.now();filesystemScan=undefined;}})();
}
await filesystemScan;
}
